```go
package main

import (
	"fmt"
	"sync"
)

func main() {
	var wg sync.WaitGroup
	counter := 0

	for range 8 {
		wg.Go(func() {
			for range 1_000 {
				counter++ // intentionally raced
			}
		})
	}
	wg.Wait()
	fmt.Println(counter)
}
```
This lesson deliberately contains a race. Validation expects `go run -race` to report DATA RACE; the visible count is not a correctness check.

```go
package main

import (
	"fmt"
	"sync"
)

func hiddenRace() int {
	value := 0
	var wg sync.WaitGroup
	for range 4 {
		wg.Go(func() { value++ })
	}
	wg.Wait()
	return value
}

func main() {
	fmt.Println("safe path only")
}
```
The unsafe helper compiles but is not executed, so a race-enabled run cannot observe its conflicting increments.

```go
package main

import (
	"fmt"
	"sync"
)

type SafeMap struct {
	mu   sync.Mutex
	data map[string]int
}

func NewSafeMap() *SafeMap {
	return &SafeMap{data: make(map[string]int)}
}

func (m *SafeMap) Set(key string, value int) {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.data[key] = value
}

func (m *SafeMap) Get(key string) (int, bool) {
	m.mu.Lock()
	defer m.mu.Unlock()
	value, ok := m.data[key]
	return value, ok
}

func main() {
	values := NewSafeMap()
	var wg sync.WaitGroup
	for i := range 20 {
		i := i
		wg.Go(func() { values.Set(fmt.Sprint(i), i) })
	}
	wg.Wait()
	value, ok := values.Get("7")
	fmt.Println(value, ok)
}
```
The map never escapes, and both reads and writes acquire the same Mutex. `go run -race` completes without a report.
